// Miniland CSV hibrido: columna 0 = CSV Magento (comas), resto columnas ; vacias
const item = $input.first();
let csvText = '';
const binaryKeys = Object.keys(item.binary || {});

for (const key of binaryKeys.length ? binaryKeys : ['data']) {
  try {
    const buffer = await this.helpers.getBinaryDataBuffer(0, key);
    const text = buffer.toString('utf-8');
    if (text?.trim()) { csvText = text; break; }
  } catch (e) {
    const binMeta = item.binary?.[key];
    if (binMeta?.data && typeof binMeta.data === 'string') {
      csvText = Buffer.from(binMeta.data, 'base64').toString('utf-8');
      if (csvText.trim()) break;
    } else if (Buffer.isBuffer(binMeta)) {
      csvText = binMeta.toString('utf-8');
      if (csvText.trim()) break;
    }
  }
}

if (!csvText?.trim()) throw new Error('CSV vacio');

csvText = csvText.replace(/^\uFEFF/, '');

function slugify(str) {
  return String(str || '').toLowerCase().normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
}
function cleanText(str) {
  if (str == null) return '';
  let s = String(str).normalize('NFC').trim();
  if (s.startsWith('"') && s.endsWith('"')) s = s.slice(1, -1).replace(/""/g, '"');
  return s.trim();
}
function norm(str) {
  return cleanText(str).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
}
function stripHtml(html) {
  return cleanText(String(html || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' '));
}
function truncate(str, max) {
  const s = cleanText(str);
  return s.length <= max ? s : s.slice(0, max);
}
function parsePrice(val) {
  const n = parseFloat(cleanText(val).replace(/\s/g, '').replace(',', '.'));
  return Number.isFinite(n) ? n : 0;
}
function isValidSku(sku) {
  const s = cleanText(sku);
  if (!s || s.length < 2 || s.length > 50) return false;
  if (/[<>]/.test(s) || s.includes('http') || /\s/.test(s)) return false;
  return /^[A-Za-z0-9._-]+$/.test(s);
}

function parseCSVAll(text, delimiter) {
  const rows = [];
  let row = [], field = '', inQuotes = false;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (inQuotes) {
      if (c === '"') {
        if (text[i + 1] === '"') { field += '"'; i++; }
        else inQuotes = false;
      } else field += c;
    } else if (c === '"') inQuotes = true;
    else if (c === delimiter) { row.push(field); field = ''; }
    else if (c === '\r') continue;
    else if (c === '\n') {
      row.push(field); field = '';
      if (row.some((x) => cleanText(x))) rows.push(row);
      row = [];
    } else field += c;
  }
  row.push(field);
  if (row.some((x) => cleanText(x))) rows.push(row);
  return rows;
}

/** Primera celda no vacia de fila externa (;) */
function outerCell(row) {
  if (!row?.length) return '';
  for (const c of row) {
    const t = cleanText(c);
    if (t) return t;
  }
  return cleanText(row[0] || '');
}

function parseInnerRow(cell) {
  if (!cell) return [];
  const parsed = parseCSVAll(cell, ',');
  return parsed[0] || [];
}

function headerIndex(header, names) {
  const h = header.map((x) => norm(x));
  for (const n of names) {
    const i = h.indexOf(n);
    if (i >= 0) return i;
  }
  for (const n of names) {
    const i = h.findIndex((x) => x === n || x.endsWith('_' + n));
    if (i >= 0) return i;
  }
  return -1;
}

function buildInnerMap(header) {
  const skuIdx = headerIndex(header, ['sku']);
  const nameIdx = headerIndex(header, ['name']);
  if (skuIdx < 0 || nameIdx < 0) return null;
  return {
    skuIdx,
    nameIdx,
    priceIdx: headerIndex(header, ['price']),
    eanIdx: headerIndex(header, ['product_ean', 'ean']),
    descIdx: headerIndex(header, ['description', 'short_description']),
    imageIdx: headerIndex(header, ['image', 'small_image', 'thumbnail']),
    refIdx: headerIndex(header, ['referencia']),
  };
}

function classifyProduct(name, description) {
  const text = norm(name + ' ' + description);
  if (text.match(/bebe|lactancia|biberon|chupete|humidificador|termometro.*digital|vigilabebes|cuna|cambiador/))
    return { c: 'bebe', s: 'Puericultura', g: null, t: null };
  if (text.match(/juego|puzzle|construccion|bloques|encajable|apilable|juguete/))
    return { c: 'juguetes', s: 'Educativos', g: null, t: null };
  if (text.match(/figura.*animal|animales.*figura|dinosaurio|insecto|granja/))
    return { c: 'juguetes', s: 'Figuras', g: null, t: null };
  if (text.match(/coche|vehiculo|tractor|camion|minimobil/))
    return { c: 'juguetes', s: 'Vehiculos', g: null, t: null };
  if (text.match(/didactico|educativo|matematicas|numeros|letras|aprendizaje/))
    return { c: 'material-escolar', s: 'Didactico', g: null, t: null };
  if (text.match(/manualidades|pintura|plastilina|modelado|arte/))
    return { c: 'material-escolar', s: 'Manualidades', g: null, t: null };
  return { c: 'sin-clasificar', s: 'Miniland pendiente', g: null, t: null };
}

// --- Parse hibrido ; + coma en columna 0 ---
const outerRows = parseCSVAll(csvText, ';');
if (!outerRows.length) throw new Error('CSV vacio tras parse ;');

const headerInner = parseInnerRow(outerCell(outerRows[0]));
let map = buildInnerMap(headerInner);

if (!map) {
  map = {
    skuIdx: 60,
    nameIdx: 42,
    priceIdx: 48,
    eanIdx: 51,
    descIdx: 8,
    imageIdx: 21,
    refIdx: -1,
  };
}

const products = [];
let skipped = 0;

for (let i = 2; i < outerRows.length; i++) {
  const inner = parseInnerRow(outerCell(outerRows[i]));
  if (inner.length < Math.max(map.skuIdx, map.nameIdx) + 1) {
    skipped++;
    continue;
  }

  let sku = cleanText(inner[map.skuIdx]);
  const name = cleanText(inner[map.nameIdx]);
  if (!isValidSku(sku) && map.refIdx >= 0) {
    const ref = cleanText(inner[map.refIdx]);
    if (isValidSku(ref)) sku = ref;
  }
  if (!isValidSku(sku) || !name || name.length > 500) {
    skipped++;
    continue;
  }

  const price = map.priceIdx >= 0 ? parsePrice(inner[map.priceIdx]) : 0;
  const ean = map.eanIdx >= 0 ? cleanText(inner[map.eanIdx]) : '';
  const description = map.descIdx >= 0 ? stripHtml(inner[map.descIdx]) : '';
  const image = map.imageIdx >= 0 ? cleanText(inner[map.imageIdx]) : '';

  const imagenes = image && image.startsWith('/')
    ? [`https://minilandgroup.com/pub/media/catalog/product${image}`]
    : image.startsWith('http') ? [image] : [];

  const cats = classifyProduct(name, description);
  products.push({
    json: {
      proveedor: 'miniland',
      ref_proveedor: truncate(sku, 100),
      sku_interno: truncate(`M${sku}`, 100),
      name: truncate(name, 500),
      description: truncate(description, 8000),
      precioBase: price,
      price: price,
      ean: truncate(ean, 50) || null,
      imagenes,
      slug: truncate(`${slugify(name)}-m${slugify(sku)}`, 200),
      stock: 999,
      categoryId: cats.c,
      subcategory: cats.s,
      grupo: cats.g,
      tipo_producto: cats.t,
      published: true,
      activo: true,
      visible_web: false,
      marca: 'Miniland',
    },
  });
}

if (products.length === 0) {
  const sample = parseInnerRow(outerCell(outerRows[2] || []));
  throw new Error(
    `0 productos. outer=${outerRows.length} headerInner=${headerInner.length} ` +
    `map=${JSON.stringify(map)} sampleCols=${sample.length} skipped=${skipped} ` +
    `sampleSku=${JSON.stringify(cleanText(sample[map.skuIdx]))} sampleName=${JSON.stringify(cleanText(sample[map.nameIdx])?.slice(0, 60))}`
  );
}

return products;

function calcularPrecioConMargen(precioBase) {
  const precio = parseFloat(precioBase);
  if (isNaN(precio) || precio <= 0) return { precioBase: 0, precioFinal: 0 };
  let multiplicador;
  if (precio < 50) multiplicador = 1.50;
  else if (precio < 100) multiplicador = 1.47;
  else if (precio < 200) multiplicador = 1.43;
  else if (precio < 400) multiplicador = 1.38;
  else multiplicador = 1.30;
  // Un solo redondeo al final (centavos), igual que Neon: ROUND(base × margen × 1.21, 2)
  const precioFinal = Math.round(precio * multiplicador * 1.21 * 100) / 100;
  return { precioBase: Math.round(precio * 100) / 100, precioFinal };
}
const results = [];
for (const item of $input.all()) {
  const precios = calcularPrecioConMargen(item.json.precioBase);
  results.push({ json: { ...item.json, precioBase: precios.precioBase, price: precios.precioFinal }});
}
return results;
